// Package gen derives the generated files (docs/formats.md section 7).
package gen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/RamXX/machinery/internal/design"
	"github.com/RamXX/machinery/internal/machine"
)

// File is one generated file, by project-relative path.
type File struct {
	Path string
	Data []byte
}

// Extra providers add generated files that belong to other packages (the
// projection for external checkers). Each returns ok=false when it does not apply.
var Extra []func(d *design.Design) (File, bool, error)

// JSON renders a value the way every generated JSON file is written: two-space
// indentation, no HTML escaping, a trailing newline.
func JSON(v any) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

type outObligation struct {
	ID      string    `json:"id"`
	Kind    string    `json:"kind"`
	Source  string    `json:"source"`
	Title   string    `json:"title"`
	Effects *[]string `json:"effects,omitempty"`
}

type obligationsDoc struct {
	Version     int             `json:"version"`
	Obligations []outObligation `json:"obligations"`
	Served      []design.Served `json:"served"`
}

// Obligations renders obligations.json.
func Obligations(d *design.Design) ([]byte, error) {
	doc := obligationsDoc{Version: 1, Obligations: []outObligation{}, Served: d.Served}
	if doc.Served == nil {
		doc.Served = []design.Served{}
	}
	for _, o := range d.Obligations {
		out := outObligation{ID: o.ID, Kind: o.Kind, Source: o.Source, Title: o.Title}
		if o.HasEffects {
			eff := o.Effects
			if eff == nil {
				eff = []string{}
			}
			out.Effects = &eff
		}
		doc.Obligations = append(doc.Obligations, out)
	}
	return JSON(doc)
}

// Dir returns the gen directory without a trailing slash.
func Dir(d *design.Design) string { return strings.TrimSuffix(d.P.Cfg.Design.Gen, "/") }

// TablePath is the path of a machine's runtime table.
func TablePath(d *design.Design, m *machine.Machine) string {
	return Dir(d) + "/tables/" + m.ID + ".table.json"
}

// Files returns every file of the gen directory, sorted by path.
func Files(d *design.Design) ([]File, error) {
	var files []File
	data, err := Obligations(d)
	if err != nil {
		return nil, err
	}
	files = append(files, File{Dir(d) + "/obligations.json", data})
	for _, m := range d.Machines {
		tj, err := JSON(m.Table)
		if err != nil {
			return nil, err
		}
		files = append(files, File{TablePath(d, m), tj})
		files = append(files, File{Dir(d) + "/tables/" + m.ID + ".table.md", TableMarkdown(m.Table)})
	}
	for _, extra := range Extra {
		f, ok, err := extra(d)
		if err != nil {
			return nil, err
		}
		if ok {
			files = append(files, f)
		}
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Path < files[j].Path })
	return files, nil
}

func cell(names []string) string {
	if len(names) == 0 {
		return "-"
	}
	return strings.Join(names, ", ")
}

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return strings.ReplaceAll(s, "|", "\\|")
}

// TableMarkdown renders the readable form of a runtime table.
func TableMarkdown(t *machine.Table) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, "# Transition table: %s\n\n", t.Machine)
	fmt.Fprintf(&b, "Generated by machinery gen from %s. Do not edit.\n\n", t.Source)
	if len(t.Entries) > 0 {
		fmt.Fprintf(&b, "Tag %s, initial state %s, entry states %s.\n\n", t.Tag, t.Initial, strings.Join(t.Entries, ", "))
	} else {
		fmt.Fprintf(&b, "Tag %s, initial state %s.\n\n", t.Tag, t.Initial)
	}
	b.WriteString("## States\n\n| state | kind | resting | entry | exit | invoke |\n|---|---|---|---|---|---|\n")
	for _, s := range t.States {
		rest := "no"
		if s.Resting {
			rest = "yes"
		}
		fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %s |\n", s.Path, s.Kind, rest, cell(s.Entry), cell(s.Exit), cell(s.Invoke))
	}
	b.WriteString("\n## Transitions\n\n| id | source | trigger | guard | target | effects |\n|---|---|---|---|---|---|\n")
	for _, tr := range t.Transitions {
		target := tr.Target
		if target == "" {
			target = "(internal)"
		}
		fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %s |\n", tr.ID, tr.Source, machine.Trigger(tr.Kind, tr.Event), orDash(tr.Guard), target, cell(tr.Effects))
	}
	var callers []machine.Transition
	for _, tr := range t.Transitions {
		if len(tr.Requires) > 0 {
			callers = append(callers, tr)
		}
	}
	if len(callers) > 0 {
		b.WriteString("\n## Callers\n\n| id | requires |\n|---|---|\n")
		for _, tr := range callers {
			fmt.Fprintf(&b, "| %s | %s |\n", tr.ID, orDash(strings.Join(tr.Requires, ", ")))
		}
	}
	if len(t.Ignores) > 0 {
		b.WriteString("\n## Ignores\n\n| id | state | event | reason |\n|---|---|---|---|\n")
		for _, ig := range t.Ignores {
			fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", ig.ID, ig.State, ig.Event, orDash(ig.Reason))
		}
	}
	if len(t.Refusals) > 0 {
		b.WriteString("\n## Refusals\n\n| id | state | handler | disposition |\n|---|---|---|---|\n")
		for _, rf := range t.Refusals {
			fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", rf.ID, rf.State, rf.Handler, orDash(rf.Disposition))
		}
	}
	if len(t.Clauses) > 0 {
		b.WriteString("\n## Guard clauses\n\n| id | transition | guard | clause |\n|---|---|---|---|\n")
		for _, cl := range t.Clauses {
			fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", cl.ID, cl.Transition, cl.Guard, cl.Clause)
		}
	}
	return []byte(b.String())
}

// DriftKind says how a generated file differs from the tree.
type DriftKind int

const (
	Stale DriftKind = iota
	Missing
	Unexpected
)

// Difference is one gen-drift finding.
type Difference struct {
	Path string
	Kind DriftKind
}

// Compare regenerates in memory and compares with the gen directory.
func Compare(d *design.Design) ([]Difference, int, error) {
	files, err := Files(d)
	if err != nil {
		return nil, 0, err
	}
	want := map[string][]byte{}
	for _, f := range files {
		want[f.Path] = f.Data
	}
	var diffs []Difference
	for _, f := range files {
		got, err := d.P.Read(f.Path)
		switch {
		case err != nil:
			diffs = append(diffs, Difference{f.Path, Missing})
		case !bytes.Equal(got, f.Data):
			diffs = append(diffs, Difference{f.Path, Stale})
		}
	}
	onDisk, err := d.P.Glob([]string{Dir(d) + "/**"})
	if err != nil {
		return nil, 0, err
	}
	for _, f := range onDisk {
		if _, ok := want[f]; !ok {
			diffs = append(diffs, Difference{f, Unexpected})
		}
	}
	sort.Slice(diffs, func(i, j int) bool { return diffs[i].Path < diffs[j].Path })
	return diffs, len(files), nil
}

// Write writes every generated file atomically and returns the paths written
// (those whose content changed or that did not exist).
func Write(d *design.Design) ([]string, error) {
	files, err := Files(d)
	if err != nil {
		return nil, err
	}
	var written []string
	for _, f := range files {
		if got, err := d.P.Read(f.Path); err == nil && bytes.Equal(got, f.Data) {
			continue
		}
		if err := d.P.WriteAtomic(f.Path, f.Data); err != nil {
			return written, err
		}
		written = append(written, f.Path)
	}
	return written, nil
}
